<template>
 <view class="agency-page feature-page">
  <image class="agency-background" src="/static/partner/bg-overview.png" mode="scaleToFill"/>
  <view class="agency-heading">脑商代理中心</view>
  <FeaturePageState :status="status" :error="error" @retry="load"/>
  <template v-if="status==='ready' && overview">
   <view class="agency-identity">
    <view><view class="agency-title">{{agencyTitle}}</view><view class="agency-subtitle"><text>{{identityLabel}}</text><button @click="contextOpen=true">切换↔</button></view></view>
    <button class="agency-switch" @click="contextOpen=true"><image src="/static/common/icon-switch.png" mode="aspectFit"/><text>切换模块</text></button>
   </view>
   <view class="agency-summary">
    <button @click="open('team')"><image src="/static/partner/icon-team.png" mode="aspectFit"/><view><text>我的团队</text><strong>{{overview.teamCount ?? '—'}}人</strong></view></button>
    <view class="agency-summary-divider"/>
    <button @click="open('income')"><image src="/static/partner/icon-agency-income.png" mode="aspectFit"/><view><text>代理收益</text><strong>¥{{money(overview.agencyIncome ?? overview.available)}}</strong></view></button>
   </view>
   <view class="agency-relation-grid">
    <button v-for="kind in relations" :key="kind.key" class="agency-relation" @click="relationOpen=true">
     <view class="agency-relation-label">{{kind.label}}</view>
     <image v-if="overview[kind.key]?.avatarUrl" class="agency-relation-avatar" :src="overview[kind.key].avatarUrl" mode="aspectFill"/>
     <view v-else class="agency-avatar">{{(overview[kind.key]?.name || '—').slice(0,1)}}</view>
     <view class="agency-relation-copy"><view><text>{{overview[kind.key]?.name || '暂未提供'}}</text><em>{{overview[kind.key]?.agencyLabel || '—'}}</em></view><text>{{overview[kind.key]?.regionLabel || overview[kind.key]?.scopeLabel || '信息待后台提供'}}</text></view>
    </button>
   </view>
   <view class="agency-benefits">
    <view class="agency-benefit-title"><text>✦</text> 等级权益 <text>✦</text></view>
    <view class="agency-tiers"><button v-for="item in overview.benefits" :key="item.id" :class="{selected:tierId===item.id}" @click="tierId=item.id">{{item.label}}</button></view>
    <ManagedRichContent v-if="benefit" :content="benefit.content"/>
    <EmptyState v-if="!benefit?.content?.nodes?.length" text="这里还没有内容～"/>
   </view>
  </template>
  <view v-if="contextOpen" class="agency-mask" @click.self="contextOpen=false"><view class="agency-sheet"><view class="agency-sheet-title">切换身份<button aria-label="关闭身份切换" @click="contextOpen=false"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><view v-for="group in contextGroups" :key="group.key" class="agency-context-group"><text>{{group.label}}</text><button v-for="item in group.items" :key="item.id" @click="chooseContext(item.id)"><view><view>{{displayContext(item)}}</view><text>{{item.scopeLabel}}</text></view><image :src="item.id===context?.id?'/static/common/icon-radio-checked.png':'/static/common/icon-chevron-right.png'" mode="aspectFit"/></button></view></view></view>
  <view v-if="relationOpen" class="agency-mask relation-mask" @click.self="relationOpen=false"><view class="agency-relation-sheet"><button class="relation-close" aria-label="关闭关系信息" @click="relationOpen=false">×</button><view v-for="kind in relations" :key="kind.key" class="relation-detail-card"><view class="relation-detail-copy"><view><text>{{overview[kind.key]?.name || '暂未提供'}}</text><em>{{relationPartnerLabel(kind.key)}}</em></view><text>{{relationIdentityLabel(kind.key)}}：{{overview[kind.key]?.agencyLabel || overview[kind.key]?.partnerLabel || '—'}}</text><text>联系方式：{{overview[kind.key]?.phone || '—'}}</text><text>{{relationRegionLabel(kind.key)}}：{{overview[kind.key]?.regionLabel || overview[kind.key]?.scopeLabel || '—'}}</text></view><view class="relation-photo"><image v-if="overview[kind.key]?.avatarUrl" :src="overview[kind.key].avatarUrl" mode="aspectFill"/><view v-else>{{(overview[kind.key]?.name || '—').slice(0,1)}}</view><text>{{kind.label}}</text></view></view></view></view>
  <AppTabBar active="partners"/>
 </view>
</template>

<script setup>
import {computed, onMounted, onUnmounted, ref} from 'vue'
import {useAuth} from '../composables/useAuth'
import {useAppTabBar} from '../composables/useAppTabBar'
import {money} from '../features/exclusive/format'
import {getBusinessContext, getBusinessContexts, getBusinessOverview, selectBusinessContext} from '../services/business'
import FeaturePageState from './FeaturePageState.vue'
import ManagedRichContent from './ManagedRichContent.vue'
import EmptyState from './EmptyState.vue'
import AppTabBar from './AppTabBar.vue'
useAuth();useAppTabBar()
const status=ref('loading'),error=ref(''),overview=ref(null),contexts=ref([]),tierId=ref(''),contextOpen=ref(false),relationOpen=ref(false)
let active=true,epoch=0,selectedId=''
const context=computed(()=>overview.value?.context)
const agencyTitle=computed(()=>context.value?.regionLabel || context.value?.label || '区域代理')
const identityLabel=computed(()=>({PROVINCE:'省代',CITY:'市代',COUNTY:'区县代理',STORE:'单店代理'})[context.value?.agencyType] || context.value?.scopeLabel || '区域代理')
const benefit=computed(()=>overview.value?.benefits?.find(item=>item.id===tierId.value))
const relations=[{key:'superior',label:'区域上级'},{key:'referrer',label:'推荐人'}]
const typeMeta={PROVINCE:'省代',CITY:'市代',COUNTY:'区代',STORE:'单店'}
const contextGroups=computed(()=>['PROVINCE','CITY','COUNTY','STORE'].map(key=>({key,label:typeMeta[key],items:contexts.value.filter(item=>item.agencyType===key)})).filter(group=>group.items.length))
function displayContext(item){return item.regionLabel || item.label}
function relationPartnerLabel(key){return overview.value?.[key]?.partnerLabel || overview.value?.[key]?.agencyLabel || '—'}
function relationIdentityLabel(key){return key==='superior'?'代理等级':'合伙等级'}
function relationRegionLabel(key){return key==='superior'?'代理地区':'所在地区'}
async function load(){const current=++epoch;status.value='loading';error.value='';contextOpen.value=false;relationOpen.value=false;try{const rows=await getBusinessContexts();const ctx=await getBusinessContext('agency',selectedId||undefined);const result=await getBusinessOverview('agency',ctx.id);if(!active||current!==epoch)return;contexts.value=rows.filter(item=>item.module==='agency');overview.value=result;selectedId=ctx.id;tierId.value=result.benefits.some(item=>item.id===tierId.value)?tierId.value:result.benefits[0]?.id||'';status.value='ready'}catch(reason){if(active&&current===epoch){error.value=reason.message||'代理工作台加载失败';status.value=reason.code==='FORBIDDEN'?'forbidden':'error'}}}
async function chooseContext(id){try{const selected=await selectBusinessContext(id);selectedId=selected.id;await load()}catch(reason){uni.showToast({title:reason.message||'切换失败',icon:'none'})}}
function open(tool){uni.navigateTo({url:`/pages/agency/${tool}?contextId=${encodeURIComponent(context.value.id)}`})}
onMounted(load);onUnmounted(()=>{active=false;++epoch})
defineExpose({refresh:load})
</script>

