;border:1rpx solid #4174d2;border-radius:18rpx;background:linear-gradient(160deg,#254c91 0%,#17336a 48%,#152148 100%);box-shadow:inset 0 1rpx rgba(205,233,255,.3);color:#fff;text-align:left;overflow:visible}.agency-relation-label{position:absolute;z-index:2;top:0;left:50%;min-width:120rpx;transform:translate(-50%,-1rpx);padding:8rpx 12rpx;border-radius:0 0 17rpx 17rpx;background:linear-gradient(90deg,#01b8f4,#315bff);color:#052c73;text-align:center;font-size:25rpx;font-weight:700;white-space:nowrap}.agency-relation-avatar,.agency-avatar{position:absolute;top:70rpx;left:18rpx;width:76rpx;height:76rpx;border:5rpx solid #69d7ff;border-radius:50%;background:#2f5da5;box-sizing:border-box}.agency-relation-avatar{object-fit:cover}.agency-avatar{display:flex;align-items:center;justify-content:center;color:#152952;font-size:28rpx;font-weight:700}.agency-relation-copy{min-width:0;margin-left:94rpx;line-height:1.45;overflow:hidden}.agency-relation-copy>view{display:flex;align-items:center;gap:8rpx;white-space:nowrap}.agency-relation-copy>view>text{font-size:26rpx;font-weight:700;overflow:hidden;text-overflow:ellipsis}.agency-relation-copy em,.relation-detail-copy em{padding:3rpx 12rpx;border-radius:22rpx;background:#ddecff;color:#23427a;font-size:19rpx;font-style:normal;white-space:nowrap}.agency-relation-copy>text{display:block;margin-top:8rpx;color:#aebbd8;font-size:21rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.agency-benefits{min-height:470rpx;padding:34rpx 32rpx 26rpx;border-radius:34rpx 34rpx 0 0;background:linear-gradient(#293b68,#22294d)}.agency-benefit-title{text-align:center;font-size:29rpx;font-weight:700}.agency-benefit-title text{padding:0 12rpx;color:#d7e6ff}.agency-tiers{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16rpx;margin:24rpx 0}.agency-tiers button{margin:0;padding:6rpx;background:#445174;color:#a8b5cb;border-radius:28rpx;font-size:22rpx;line-height:1.7}.agency-tiers button.selected{background:radial-gradient(ellipse,#